// ─────────────────────────────────────────────────────────────────────────────
// Build Synthetic Failure Events (Manual Test Trigger path)
// Emits a webhook-shaped request carrying a batch of fictitious Chili Piper
// router events. Paths covered: territory routing (US-East, EMEA), existing
// owner continuity, default pool, cooldown duplicate, a successful booking
// (ignored), an invalid email (rejected) and a replayed event ID.
// ─────────────────────────────────────────────────────────────────────────────
const now = Date.now();
const iso = (msAgo) => new Date(now - msAgo).toISOString();
const ev = (id, type, lead, extra = {}) => ({
  id, event: type, occurredAt: iso(60000), routerName: 'Inbound Demo Router (synthetic)',
  lead, routing: { status: type.includes('booked') ? 'booked' : 'failed', reason: extra.reason || null }, meetingUrl: extra.meetingUrl || null, ...extra.more,
});

return [{
  json: {
    headers: { 'content-type': 'application/json', 'user-agent': 'synthetic-router-test' },
    params: {},
    query: { source: 'chilipiper' },
    body: [
      ev('cp-syn-0001', 'routing.failed', { firstName: 'Alex', lastName: 'Miller', email: 'alex@company.example', company: 'Company Example Ltd', phone: '+1 555 010 1001', country: 'US', state: 'NY', companySize: '201-500' }, { reason: 'no_rep_available', meetingUrl: 'https://scheduler.example/m/cp-syn-0001' }),
      ev('cp-syn-0002', 'routing.no_match', { first_name: 'Priya', last_name: 'Shah', email: 'priya@brightfield.example', company_name: 'Brightfield Example', country: 'GB' }, { reason: 'no_matching_queue' }),
      ev('cp-syn-0003', 'routing.abandoned', { firstName: 'Diego', lastName: 'Ramos', email: 'diego@sandcastle.example', company: 'Sandcastle Example', country: 'BR' }, { reason: 'prospect_closed_scheduler' }),
      ev('cp-syn-0004', 'routing.failed', { firstName: 'Morgan', lastName: 'Diaz', email: 'morgan@company.example', company: 'Company Example Ltd', country: 'US', state: 'CA' }, { reason: 'calendar_sync_error' }),
      ev('cp-syn-0005', 'meeting.booked', { firstName: 'Jamie', lastName: 'Fox', email: 'jamie@company.example', company: 'Company Example Ltd' }),
      ev('cp-syn-0006', 'routing.failed', { firstName: 'Sam', lastName: 'Ortiz', email: 'not-an-email', company: 'Unknown' }, { reason: 'no_rep_available' }),
      ev('cp-syn-0001', 'routing.failed', { firstName: 'Alex', lastName: 'Miller', email: 'alex@company.example', company: 'Company Example Ltd', country: 'US', state: 'NY' }, { reason: 'no_rep_available' }),
    ],
    webhookUrl: 'https://n8n.example/webhook/routing/fallback',
    executionMode: 'test',
  },
}];

// ─────────────────────────────────────────────────────────────────────────────
// Parse, Verify & Normalize Events
// 1. Detects the source (?source= query, signature header, or body shape).
// 2. Verifies authenticity (skipped only in SANDBOX_MODE):
//      calendly   → Calendly-Webhook-Signature  t=…,v1=HMAC-SHA256(key, `${t}.${raw}`)
//      chilipiper → CHILIPIPER_SIGNATURE_HEADER: HMAC-SHA256(secret, raw) hex, or static token
//      hubspot    → X-HubSpot-Signature-v3 (HMAC-SHA256 over method + URI + body + timestamp)
// 3. Normalizes Chili Piper, Calendly routing-form and HubSpot payloads into
//    one lead/failure shape, keeps only failed routings, validates emails and
//    de-duplicates event IDs (in-request and across production executions).
//
// Security note: webhook signing secrets are read here, in memory, only because
// an inbound HMAC cannot be verified in an HTTP Request field. They are never
// written to node output.
// ─────────────────────────────────────────────────────────────────────────────
const item = $input.first();
const req = item.json;
const cfg = req.config;
const headers = Object.fromEntries(Object.entries(req.headers || {}).map(([k, v]) => [String(k).toLowerCase(), String(v)]));
const now = Date.now();

// ── Raw body (needed for exact HMAC) ──────────────────────────────────────
let rawBody = null;
let rawSource = 'reconstructed';
try {
  const bin = item.binary && item.binary.data;
  if (bin && bin.data && !String(bin.id || '').length) { rawBody = Buffer.from(bin.data, 'base64').toString('utf8'); rawSource = 'raw'; }
} catch (e) { rawBody = null; }
if (rawBody === null) rawBody = typeof req.body === 'string' ? req.body : JSON.stringify(req.body ?? '');

let body = req.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
if ((body === null || body === undefined || (typeof body === 'object' && !Array.isArray(body) && !Object.keys(body).length)) && rawSource === 'raw') {
  try { body = JSON.parse(rawBody); } catch (e) { body = null; }
}

// ── Source detection ──────────────────────────────────────────────────────
const q = String(req.query?.source || '').toLowerCase();
let source = ['chilipiper', 'calendly', 'hubspot'].includes(q) ? q : null;
if (!source && headers['calendly-webhook-signature']) source = 'calendly';
if (!source && headers['x-hubspot-signature-v3']) source = 'hubspot';
if (!source && headers[cfg.chilipiperSignatureHeader]) source = 'chilipiper';
if (!source && body && (String(body.event || '').startsWith('routing_form_submission') || body.payload?.routing_form)) source = 'calendly';
if (!source && body && (body.objectId || body.hs_object_id || body.properties?.email)) source = 'hubspot';
if (!source) source = 'chilipiper';

// ── Signature verification ────────────────────────────────────────────────
let signature = 'skipped (sandbox)';
if (!cfg.sandboxMode && cfg.requireSignature) {
  let crypto;
  try { crypto = require('crypto'); } catch (e) { throw new Error('Signature verification needs NODE_FUNCTION_ALLOW_BUILTIN=crypto.'); }
  const readSecret = (name) => { try { return String($env[name] || ''); } catch (e) { return ''; } };
  const safeEq = (a, b) => { const A = Buffer.from(String(a)); const B = Buffer.from(String(b)); return A.length === B.length && crypto.timingSafeEqual(A, B); };
  const hmac = (key, data, enc) => crypto.createHmac('sha256', key).update(data, 'utf8').digest(enc);

  if (source === 'calendly') {
    const key = readSecret('CALENDLY_WEBHOOK_SIGNING_KEY');
    if (!key) throw new Error('Rejected: CALENDLY_WEBHOOK_SIGNING_KEY is not set.');
    const parts = Object.fromEntries(String(headers['calendly-webhook-signature'] || '').split(',').map((p) => p.split('=').map((s) => s.trim())));
    if (!parts.t || !parts.v1) throw new Error('Rejected: missing Calendly-Webhook-Signature header.');
    if (Math.abs(now / 1000 - Number(parts.t)) > cfg.signatureToleranceSec) throw new Error('Rejected: Calendly signature timestamp outside tolerance (possible replay).');
    if (!safeEq(parts.v1, hmac(key, `${parts.t}.${rawBody}`, 'hex'))) throw new Error('Rejected: Calendly signature mismatch.');
  } else if (source === 'hubspot') {
    const secret = readSecret('HUBSPOT_APP_CLIENT_SECRET');
    const sig = headers['x-hubspot-signature-v3'];
    const ts = headers['x-hubspot-request-timestamp'];
    if (!secret || !sig || !ts) throw new Error('Rejected: HubSpot v3 signature, timestamp or HUBSPOT_APP_CLIENT_SECRET missing.');
    if (Math.abs(now - Number(ts)) > cfg.signatureToleranceSec * 1000) throw new Error('Rejected: HubSpot timestamp outside tolerance.');
    if (!safeEq(sig, hmac(secret, `POST${cfg.webhookPublicUrl || req.webhookUrl}${rawBody}${ts}`, 'base64'))) throw new Error('Rejected: HubSpot v3 signature mismatch.');
  } else {
    const secret = readSecret('CHILIPIPER_WEBHOOK_SECRET');
    if (!secret) throw new Error('Rejected: CHILIPIPER_WEBHOOK_SECRET is not set.');
    const provided = String(headers[cfg.chilipiperSignatureHeader] || '').replace(/^sha256=/i, '');
    if (!provided) throw new Error(`Rejected: missing ${cfg.chilipiperSignatureHeader} header.`);
    const ok = cfg.chilipiperSignatureMode === 'token' ? safeEq(provided, secret) : safeEq(provided.toLowerCase(), hmac(secret, rawBody, 'hex'));
    if (!ok) throw new Error('Rejected: Chili Piper signature mismatch.');
  }
  signature = `verified (${source}, ${rawSource} body)`;
} else if (!cfg.sandboxMode) {
  signature = 'disabled (REQUIRE_SIGNATURE=false)';
}

// ── Normalisation helpers ─────────────────────────────────────────────────
const pick = (...vals) => { for (const v of vals) if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim(); return null; };
const clean = (v, max) => (v === null ? null : String(v).replace(/[\u0000-\u001F\u007F<>]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max));
const EMAIL_RE = /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,63}$/i;
const FAILURE_RE = /(fail|no[_ .-]?match|not[_ .-]?booked|no[_ .-]?availab|abandon|timeout|error|unrouted|no[_ .-]?rep|dropped)/i;
const SUCCESS_RE = /(booked|scheduled|routed[_ .-]?success|completed)/i;

function fromChiliPiper(e) {
  const lead = e.lead || e.prospect || e.guest || e.contact || e.invitee || {};
  const f = e.formData || e.fields || e.answers || {};
  const type = pick(e.event, e.type, e.eventType, e.name) || '';
  const status = pick(e.routing?.status, e.status, e.outcome) || '';
  const failed = FAILURE_RE.test(type) || FAILURE_RE.test(status);
  const succeeded = !failed && (SUCCESS_RE.test(type) || SUCCESS_RE.test(status));
  return {
    eventId: pick(e.id, e.eventId, e.uuid, e.requestId),
    type: type || status || 'unknown',
    failed: failed || (!succeeded && Boolean(pick(e.reason, e.failureReason, e.routing?.reason, e.error?.message))),
    reason: pick(e.routing?.reason, e.failureReason, e.reason, e.error?.message, e.error?.code, status, type),
    occurredAt: pick(e.occurredAt, e.timestamp, e.createdAt, e.created_at),
    meetingLink: pick(e.meetingUrl, e.bookingUrl, e.rescheduleUrl, e.schedulingLink, e.link),
    routerName: pick(e.routerName, e.router?.name, e.queue?.name, e.queue),
    lead: {
      firstName: pick(lead.firstName, lead.first_name, lead.firstname, f.firstName, f.first_name, f.FirstName),
      lastName: pick(lead.lastName, lead.last_name, lead.lastname, f.lastName, f.last_name, f.LastName),
      email: pick(lead.email, lead.workEmail, f.email, f.Email),
      company: pick(lead.company, lead.companyName, lead.company_name, f.company, f.Company),
      phone: pick(lead.phone, lead.phoneNumber, f.phone, f.Phone),
      country: pick(lead.country, lead.countryCode, f.country, f.Country),
      state: pick(lead.state, lead.region, f.state, f.State),
      companySize: pick(lead.companySize, lead.employees, f.companySize, f.employees),
    },
  };
}
function fromCalendly(e) {
  const p = e.payload || {};
  const qa = Array.isArray(p.questions_and_answers) ? p.questions_and_answers : [];
  const ans = (re) => { const hit = qa.find((x) => re.test(String(x.question || ''))); return hit ? pick(hit.answer) : null; };
  const resultType = pick(p.result?.type) || 'unknown';
  return {
    eventId: pick(p.uri, e.id),
    type: `${pick(e.event) || 'calendly'}:${resultType}`,
    failed: String(e.event || '').startsWith('routing_form_submission') && cfg.calendlyFailureResults.includes(resultType),
    reason: `routing_result_${resultType}`,
    occurredAt: pick(p.created_at, e.created_at),
    meetingLink: resultType === 'external_url' ? pick(p.result?.value) : null,
    routerName: pick(p.routing_form),
    lead: {
      firstName: ans(/first\s*name/i), lastName: ans(/last\s*name|surname/i), email: ans(/e-?mail/i), company: ans(/company|organi[sz]ation/i),
      phone: ans(/phone|mobile/i), country: ans(/country/i), state: ans(/state|province|region/i), companySize: ans(/employees|company size/i),
    },
  };
}
function fromHubSpot(e) {
  const pr = e.properties || e.contact || e;
  return {
    eventId: pick(e.eventId, e.id, e.objectId ? `hs-${e.objectId}-${pick(e.occurredAt, e.timestamp) || ''}` : null),
    type: pick(e.subscriptionType, e.type, 'hubspot.fallback_requested'),
    failed: true,
    reason: pick(e.reason, pr.routing_failure_reason, pr.routing_fallback_reason, 'hubspot_fallback_requested'),
    occurredAt: pick(e.occurredAt, e.timestamp),
    meetingLink: pick(pr.meeting_link, e.meetingLink),
    routerName: pick(e.workflowName, 'HubSpot workflow'),
    lead: {
      firstName: pick(pr.firstname, pr.firstName), lastName: pick(pr.lastname, pr.lastName), email: pick(pr.email), company: pick(pr.company),
      phone: pick(pr.phone, pr.mobilephone), country: pick(pr.country), state: pick(pr.state), companySize: pick(pr.numberofemployees),
    },
    hubspotContactId: pick(e.objectId, pr.hs_object_id),
  };
}

// ── Normalise, filter, de-duplicate ───────────────────────────────────────
const rawEvents = Array.isArray(body) ? body : body ? [body] : [];
const counters = { received: rawEvents.length, notFailure: 0, invalidEmail: 0, duplicateInRequest: 0, replayed: 0, overCap: 0, accepted: 0 };
const rejected = [];
let store = null;
try { store = $getWorkflowStaticData('global'); } catch (e) { store = null; }
if (store) {
  store.seenEvents = store.seenEvents || {};
  for (const [k, t] of Object.entries(store.seenEvents)) if (now - t > cfg.eventDedupeHours * 3600000) delete store.seenEvents[k];
}

const seen = new Set();
const events = [];
for (const raw of rawEvents) {
  const n = source === 'calendly' ? fromCalendly(raw) : source === 'hubspot' ? fromHubSpot(raw) : fromChiliPiper(raw);
  n.eventId = clean(n.eventId || `${source}-${n.lead.email}-${n.occurredAt || now}`, 200);
  if (!n.failed) { counters.notFailure += 1; continue; }
  const email = (n.lead.email || '').toLowerCase();
  if (!EMAIL_RE.test(email)) { counters.invalidEmail += 1; rejected.push({ eventId: n.eventId, reason: 'invalid_email' }); continue; }
  if (seen.has(n.eventId)) { counters.duplicateInRequest += 1; continue; }
  seen.add(n.eventId);
  if (store && !cfg.sandboxMode && store.seenEvents[n.eventId]) { counters.replayed += 1; continue; }
  if (events.length >= cfg.maxEventsPerRequest) { counters.overCap += 1; continue; }

  events.push({
    eventId: n.eventId,
    source,
    type: clean(n.type, 80),
    reason: clean(n.reason, 120) || 'unspecified',
    occurredAt: n.occurredAt && !Number.isNaN(Date.parse(n.occurredAt)) ? new Date(Date.parse(n.occurredAt)).toISOString() : new Date(now).toISOString(),
    meetingLink: n.meetingLink && /^https:\/\//i.test(n.meetingLink) ? clean(n.meetingLink, 500) : null,
    routerName: clean(n.routerName, 120),
    hubspotContactId: n.hubspotContactId || null,
    lead: {
      firstName: clean(n.lead.firstName, 80), lastName: clean(n.lead.lastName, 80), email,
      company: clean(n.lead.company, 160), phone: clean(n.lead.phone, 40),
      country: n.lead.country ? clean(n.lead.country, 60).toUpperCase() : null, state: n.lead.state ? clean(n.lead.state, 60).toUpperCase() : null,
      companySize: clean(n.lead.companySize, 40),
    },
  });
}
if (store && !cfg.sandboxMode) for (const e of events) store.seenEvents[e.eventId] = now;
counters.accepted = events.length;

return [{ json: { source, signature, rawBodySource: rawSource, counters, rejected, events } }];

// ─────────────────────────────────────────────────────────────────────────────
// Mock HubSpot Context (SANDBOX_MODE=true)
// Fictitious HubSpot contacts (matched by email) and active owners, in the
// same shape "Assemble Routing Context" emits on the live path.
// ─────────────────────────────────────────────────────────────────────────────
const parsed = $('Parse, Verify & Normalize Events').first().json;
const MIN_MS = 60 * 1000;
const ago = (m) => new Date(Date.now() - m * MIN_MS).toISOString();

const CONTACTS = {
  'alex@company.example': { id: '9100000001', properties: { email: 'alex@company.example', firstname: 'Alex', lastname: 'Miller', company: 'Company Example Ltd', phone: null, lifecyclestage: 'lead', hubspot_owner_id: '83000002', routing_fallback_at: null } },
  'morgan@company.example': { id: '9100000004', properties: { email: 'morgan@company.example', firstname: 'Morgan', lastname: 'Diaz', company: 'Company Example Ltd', phone: null, lifecyclestage: 'marketingqualifiedlead', hubspot_owner_id: null, routing_fallback_at: ago(20) } },
};
const owners = [
  { id: '83000001', email: 'sdr.east.one@example.com', firstName: 'Riley', lastName: 'East', archived: false },
  { id: '83000002', email: 'sdr.east.two@example.com', firstName: 'Casey', lastName: 'Harbor', archived: false },
  { id: '83000003', email: 'sdr.emea.one@example.com', firstName: 'Noor', lastName: 'Atlas', archived: false },
  { id: '83000004', email: 'sdr.pool.one@example.com', firstName: 'Jordan', lastName: 'Pool', archived: false },
  { id: '83000009', email: 'sdr.fallback@example.com', firstName: 'Fallback', lastName: 'Desk', archived: false },
];

const contacts = {};
for (const e of parsed.events) if (CONTACTS[e.lead.email]) contacts[e.lead.email] = CONTACTS[e.lead.email];
return [{ json: { source: 'synthetic-fixtures', contacts, owners } }];

// ─────────────────────────────────────────────────────────────────────────────
// Assemble Routing Context
// Joins the HubSpot contact search (by email) and the active owners list into
// the same shape the sandbox emits.
// ─────────────────────────────────────────────────────────────────────────────
const contacts = {};
for (const item of $('HubSpot: Find Contacts by Email').all()) {
  for (const r of Array.isArray(item.json.results) ? item.json.results : []) {
    const email = String(r.properties?.email || '').toLowerCase();
    if (email && !contacts[email]) contacts[email] = { id: String(r.id), properties: r.properties };
  }
}
const owners = [];
for (const item of $input.all()) {
  for (const o of Array.isArray(item.json.results) ? item.json.results : []) {
    if (o.archived === true) continue;
    owners.push({ id: String(o.id), email: String(o.email || '').toLowerCase(), firstName: o.firstName || null, lastName: o.lastName || null, archived: false });
  }
}
return [{ json: { source: 'hubspot', contacts, owners } }];

// ─────────────────────────────────────────────────────────────────────────────
// Active SDR Round-Robin Router
// For every failed routing event:
//   0. cooldown        → suppress if the contact already had a fallback within
//                        FALLBACK_COOLDOWN_MINUTES (retries, double submits)
//   1. existing_owner  → keep an active owner who is in the SDR pool
//   2. territory_rr    → weighted round-robin among active SDRs of the lead's
//                        territory (TERRITORY_RULES), honouring daily capacity
//   3. default_pool_rr → weighted round-robin among SDRs tagged "default" / "*"
//   4. default_sdr     → DEFAULT_SDR_EMAIL
// "Active" means: a non-archived HubSpot owner, not listed in
// SDR_UNAVAILABLE_EMAILS. Cursors and daily counts persist in workflow static
// data for production executions.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const parsed = $('Parse, Verify & Normalize Events').first().json;
const ctx = $input.first().json;
const now = Date.now();
const today = new Date(now).toISOString().slice(0, 10);

const SANDBOX_POOL = [
  { email: 'sdr.east.one@example.com', territories: ['US-East'], weight: 1, maxDailyFallbacks: 20, slackUserId: 'U0SYNEAST1' },
  { email: 'sdr.east.two@example.com', territories: ['US-East'], weight: 1, maxDailyFallbacks: 20, slackUserId: 'U0SYNEAST2' },
  { email: 'sdr.emea.one@example.com', territories: ['EMEA'], weight: 1, maxDailyFallbacks: 20 },
  { email: 'sdr.pool.one@example.com', territories: ['default', 'US-West'], weight: 2, maxDailyFallbacks: 30 },
];
const SANDBOX_TERRITORIES = [
  { name: 'US-East', countries: ['US', 'USA', 'UNITED STATES'], states: ['NY', 'NJ', 'MA', 'PA', 'CT', 'VA', 'FL', 'GA', 'NC'] },
  { name: 'US-West', countries: ['US', 'USA', 'UNITED STATES'], states: ['CA', 'WA', 'OR', 'NV', 'AZ', 'CO', 'UT'] },
  { name: 'EMEA', countries: ['GB', 'UK', 'DE', 'FR', 'NL', 'IE', 'ES', 'IT', 'SE', 'AE', 'ZA'] },
];
const parseJson = (s, fallback, label) => {
  if (!s) return fallback;
  try { const v = JSON.parse(s); return Array.isArray(v) ? v : fallback; } catch (e) { throw new Error(`${label} is not valid JSON.`); }
};
const pool = parseJson(cfg.sdrPoolJson, cfg.sandboxMode ? SANDBOX_POOL : [], 'SDR_POOL')
  .map((p) => ({ email: String(p.email || '').toLowerCase(), territories: (p.territories || ['default']).map(String), weight: Math.max(1, Math.min(10, Number(p.weight) || 1)), maxDailyFallbacks: Number(p.maxDailyFallbacks) || cfg.defaultMaxDailyFallbacks, slackUserId: p.slackUserId || null }))
  .filter((p) => p.email);
const territories = parseJson(cfg.territoryRulesJson, cfg.sandboxMode ? SANDBOX_TERRITORIES : [], 'TERRITORY_RULES')
  .map((t) => ({ name: String(t.name), countries: (t.countries || []).map((c) => String(c).toUpperCase()), states: (t.states || []).map((s) => String(s).toUpperCase()) }));

const ownersByEmail = new Map(ctx.owners.map((o) => [o.email, o]));
const ownersById = new Map(ctx.owners.map((o) => [o.id, o]));
const unavailable = new Set(cfg.unavailableEmails.map((e) => e.toLowerCase()));
const isActive = (email) => ownersByEmail.has(email) && !unavailable.has(email);
const activePool = pool.filter((p) => isActive(p.email));
const inactivePool = pool.filter((p) => !isActive(p.email)).map((p) => ({ email: p.email, reason: unavailable.has(p.email) ? 'unavailable' : 'not_an_active_owner' }));

let store = null;
try { store = $getWorkflowStaticData('global'); } catch (e) { store = null; }
// Sandbox runs use a throwaway state so synthetic events never move production cursors or counts.
const state = store && !cfg.sandboxMode ? store : {};
state.rr = state.rr || {};
state.daily = state.daily && state.daily.date === today ? state.daily : { date: today, counts: {} };
const counts = state.daily.counts;

function territoryFor(lead) {
  const country = String(lead.country || '').toUpperCase();
  const st = String(lead.state || '').toUpperCase();
  const t = territories.find((r) => r.countries.includes(country) && (!r.states.length || r.states.includes(st)));
  return t ? t.name : 'default';
}
function roundRobin(key, candidates) {
  const ring = candidates.flatMap((c) => Array(c.weight).fill(c));
  if (!ring.length) return null;
  const start = Number(state.rr[key] || 0) % ring.length;
  for (let i = 0; i < ring.length; i += 1) {
    const c = ring[(start + i) % ring.length];
    if ((counts[c.email] || 0) < c.maxDailyFallbacks) { state.rr[key] = (start + i + 1) % ring.length; return c; }
  }
  return null;
}

const results = parsed.events.map((e) => {
  const contact = ctx.contacts[e.lead.email] || null;
  const cp = contact ? contact.properties : {};
  const lastFallbackMs = Date.parse(cp.routing_fallback_at || '');
  if (Number.isFinite(lastFallbackMs) && now - lastFallbackMs < cfg.fallbackCooldownMinutes * 60000) {
    return { ...e, contact, territory: null, assignment: null, outcome: 'suppressed_cooldown', note: `previous fallback ${Math.round((now - lastFallbackMs) / 60000)} min ago` };
  }

  const territory = territoryFor(e.lead);
  let chosen = null;
  let rule = null;

  const existing = cp.hubspot_owner_id ? ownersById.get(String(cp.hubspot_owner_id)) : null;
  if (cfg.preferExistingOwner && existing && isActive(existing.email) && (cfg.allowNonPoolOwner || activePool.some((p) => p.email === existing.email))) {
    chosen = activePool.find((p) => p.email === existing.email) || { email: existing.email, slackUserId: null, maxDailyFallbacks: Infinity };
    rule = 'existing_owner';
  }
  if (!chosen) {
    const c = roundRobin(`t:${territory}`, activePool.filter((p) => p.territories.includes(territory) || p.territories.includes('*')));
    if (c) { chosen = c; rule = territory === 'default' ? 'default_pool_round_robin' : 'territory_round_robin'; }
  }
  if (!chosen && territory !== 'default') {
    const c = roundRobin('t:default', activePool.filter((p) => p.territories.includes('default') || p.territories.includes('*')));
    if (c) { chosen = c; rule = 'default_pool_round_robin'; }
  }
  if (!chosen) {
    const fallback = cfg.defaultSdrEmail.toLowerCase();
    chosen = { email: fallback, slackUserId: null, maxDailyFallbacks: Infinity };
    rule = 'default_sdr';
  }

  const owner = ownersByEmail.get(chosen.email) || null;
  counts[chosen.email] = (counts[chosen.email] || 0) + 1;
  return {
    ...e,
    contact,
    territory,
    assignment: { sdrEmail: chosen.email, ownerId: owner ? owner.id : null, sdrName: owner ? [owner.firstName, owner.lastName].filter(Boolean).join(' ') : null, slackUserId: chosen.slackUserId || null, rule },
    outcome: owner ? 'assigned' : 'unassigned_owner_not_found',
  };
});

return [{
  json: {
    results,
    routing: {
      poolSize: pool.length,
      activePool: activePool.map((p) => p.email),
      inactivePool,
      territories: territories.map((t) => t.name),
      dailyCounts: { ...counts },
      persisted: Boolean(store) && !cfg.sandboxMode && cfg.executionMode === 'production',
    },
  },
}];

// ─────────────────────────────────────────────────────────────────────────────
// Compose Fallback Payloads
// Builds the HubSpot contact upsert (by email), the fallback task and failure
// note drafts (associated after the upsert returns contact IDs), and the Slack
// alert. Existing contact data is never overwritten: identity fields are only
// sent when blank in HubSpot, lifecycle stage only moves forward, and the
// contact owner is only set when empty (CONTACT_OWNER_POLICY).
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const { results, routing } = $input.first().json;
const nowIso = new Date().toISOString();
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const blank = (v) => v === null || v === undefined || String(v).trim() === '';
const LIFECYCLE = ['subscriber', 'lead', 'marketingqualifiedlead', 'salesqualifiedlead', 'opportunity', 'customer', 'evangelist'];
const RULE_LABEL = { existing_owner: 'existing owner', territory_round_robin: 'territory round-robin', default_pool_round_robin: 'default pool round-robin', default_sdr: 'default SDR' };

const actionable = results.filter((r) => r.outcome !== 'suppressed_cooldown');
const dueIso = new Date(Date.now() + cfg.taskDueMinutes * 60000).toISOString();
const fullName = (l) => [l.firstName, l.lastName].filter(Boolean).join(' ') || l.email;

// ── Contact upserts ───────────────────────────────────────────────────────
const upserts = actionable.map((r) => {
  const ex = r.contact ? r.contact.properties : {};
  const isNew = !r.contact;
  const props = { email: r.lead.email };
  for (const [hs, val] of [['firstname', r.lead.firstName], ['lastname', r.lead.lastName], ['company', r.lead.company], ['phone', r.lead.phone], ['country', r.lead.country], ['state', r.lead.state]]) {
    if (!blank(val) && (isNew || blank(ex[hs]))) props[hs] = val;
  }
  if (cfg.updateContacts) {
    Object.assign(props, {
      routing_fallback_status: 'pending_sdr_followup',
      routing_fallback_reason: r.reason,
      routing_fallback_source: r.source,
      routing_fallback_at: nowIso,
      routing_fallback_sdr_email: r.assignment.sdrEmail,
      routing_fallback_event_id: r.eventId,
    });
    const target = cfg.lifecycleOnFallback;
    if (target && LIFECYCLE.includes(target) && LIFECYCLE.indexOf(String(ex.lifecyclestage || '')) < LIFECYCLE.indexOf(target)) props.lifecyclestage = target;
    if (r.assignment.ownerId && (cfg.contactOwnerPolicy === 'always' || (cfg.contactOwnerPolicy === 'fill_empty' && blank(ex.hubspot_owner_id)))) props.hubspot_owner_id = r.assignment.ownerId;
  }
  return { idProperty: 'email', id: r.lead.email, properties: props, _isNew: isNew };
});

// ── Task and note drafts (contact association added after the upsert) ────
const taskDrafts = cfg.createFallbackTasks ? actionable.map((r) => {
  const l = r.lead;
  const properties = {
    hs_timestamp: dueIso,
    hs_task_subject: `⚡ Routing fallback: contact ${fullName(l)}${l.company ? ` (${l.company})` : ''} now`.slice(0, 250),
    hs_task_body: [
      `<p><strong>Instant routing failed. This lead expected a live handoff.</strong></p>`,
      `<ul><li>Reason: ${esc(r.reason)}</li><li>Source: ${esc(r.source)}${r.routerName ? ` / ${esc(r.routerName)}` : ''}</li><li>Failed at: ${esc(r.occurredAt)}</li>`,
      `<li>Assigned via: ${esc(RULE_LABEL[r.assignment.rule])}${r.territory ? ` (territory ${esc(r.territory)})` : ''}</li>`,
      l.companySize ? `<li>Company size: ${esc(l.companySize)}</li>` : '',
      r.meetingLink ? `<li>Meeting link: <a href="${esc(r.meetingLink)}">${esc(r.meetingLink)}</a></li>` : '',
      '</ul><p><em>Suggested play: call within the SLA, acknowledge the scheduling issue, and book the meeting directly from your calendar.</em></p>',
      `<p><em>n8n-chilipiper-hubspot-instant-routing-fallback-handler (dhRobin Systems), event ${esc(r.eventId)}, run ${esc(cfg.runId)}.</em></p>`,
    ].join(''),
    hs_task_status: 'NOT_STARTED',
    hs_task_priority: 'HIGH',
    hs_task_type: 'CALL',
  };
  if (r.assignment.ownerId) properties.hubspot_owner_id = r.assignment.ownerId;
  return { email: l.email, properties };
}) : [];

const noteDrafts = cfg.createFallbackTasks && cfg.logFailureNotes ? actionable.map((r) => ({
  email: r.lead.email,
  properties: {
    hs_timestamp: nowIso,
    hs_note_body: `<p><strong>Routing fallback logged</strong></p><p>Source: ${esc(r.source)} · Event: ${esc(r.eventId)} · Type: ${esc(r.type)}<br>Reason: ${esc(r.reason)}<br>Assigned SDR: ${esc(r.assignment.sdrEmail)} via ${esc(RULE_LABEL[r.assignment.rule])}${r.outcome !== 'assigned' ? ' (owner not found in HubSpot; task unassigned)' : ''}</p>`,
  },
})) : [];

// ── Slack alert ───────────────────────────────────────────────────────────
const clip = (s, n) => (s.length > n ? `${s.slice(0, n - 1)}…` : s);
const mention = (a) => (a.slackUserId ? `<@${a.slackUserId}>` : a.sdrName || a.sdrEmail);
const contactLink = (r) => (cfg.portalId && r.contact ? `${cfg.hubspotUiBaseUrl}/contacts/${cfg.portalId}/record/0-1/${r.contact.id}` : null);
const leadBlocks = actionable.slice(0, 10).flatMap((r) => {
  const l = r.lead;
  const details = cfg.slackIncludeContactDetails ? `\n${l.email}${l.phone ? ` · ${l.phone}` : ''}` : '';
  const warn = r.outcome !== 'assigned' ? '\n:warning: *Assigned SDR is not an active HubSpot owner; the task is unassigned.*' : '';
  const blocks = [{
    type: 'section',
    text: { type: 'mrkdwn', text: clip(`*${fullName(l).replace(/[<>|*_~`]/g, '')}*${l.company ? ` · ${l.company.replace(/[<>|*_~`]/g, '')}` : ''}${details}\nReason: \`${r.reason}\` · Source: ${r.source}${r.territory ? ` · Territory: ${r.territory}` : ''}\nAssigned to ${mention(r.assignment)} via ${RULE_LABEL[r.assignment.rule]} · due in ${cfg.taskDueMinutes} min${warn}`, 2900) },
  }];
  const buttons = [];
  if (contactLink(r)) buttons.push({ type: 'button', text: { type: 'plain_text', text: 'Open contact' }, url: contactLink(r) });
  if (r.meetingLink) buttons.push({ type: 'button', text: { type: 'plain_text', text: 'Meeting link' }, url: r.meetingLink });
  if (buttons.length) blocks.push({ type: 'actions', elements: buttons });
  return blocks;
});
const unassigned = actionable.filter((r) => r.outcome !== 'assigned').length;
const slackPayload = {
  text: `Routing fallback: ${actionable.length} lead(s) need an SDR now`,
  blocks: [
    { type: 'header', text: { type: 'plain_text', text: `⚡ Instant routing failed: ${actionable.length} lead${actionable.length === 1 ? '' : 's'} reassigned` } },
    { type: 'context', elements: [{ type: 'mrkdwn', text: `${cfg.sandboxMode ? 'SANDBOX' : 'LIVE'} · ${cfg.dryRun ? 'DRY RUN' : cfg.createFallbackTasks ? 'tasks created' : 'tasks disabled'} · active SDRs ${routing.activePool.length}/${routing.poolSize}${unassigned ? ` · :warning: ${unassigned} unassigned` : ''}` }] },
    { type: 'divider' },
    ...leadBlocks,
    ...(actionable.length > 10 ? [{ type: 'context', elements: [{ type: 'mrkdwn', text: `+${actionable.length - 10} more. See HubSpot (routing_fallback_status = pending_sdr_followup).` }] }] : []),
    { type: 'context', elements: [{ type: 'mrkdwn', text: `n8n-chilipiper-hubspot-instant-routing-fallback-handler · run ${cfg.runId}` }] },
  ],
};

return [{
  json: {
    dryRun: cfg.dryRun,
    createFallbackTasks: cfg.createFallbackTasks,
    sendSlackAlerts: cfg.sendSlackAlerts,
    counts: { events: results.length, actionable: actionable.length, suppressed: results.length - actionable.length, unassigned, upserts: upserts.length, tasks: taskDrafts.length, notes: noteDrafts.length },
    upsertBody: { inputs: upserts.map(({ _isNew, ...u }) => u) },
    taskDrafts,
    noteDrafts,
    slackPayload,
    routing,
    outcomes: results.map((r) => ({ eventId: r.eventId, email: r.lead.email, outcome: r.outcome, rule: r.assignment?.rule || null, sdrEmail: r.assignment?.sdrEmail || null, territory: r.territory, reason: r.reason, existingContact: Boolean(r.contact), note: r.note || null })),
  },
}];

// ─────────────────────────────────────────────────────────────────────────────
// Attach Contact IDs to Tasks & Notes
// Maps the upsert response (email → contact ID) onto the task and note drafts
// and adds the HubSpot-defined associations (task→contact 204,
// note→contact 202). Drafts whose contact could not be resolved are dropped
// and reported.
// ─────────────────────────────────────────────────────────────────────────────
const composed = $('Compose Fallback Payloads').first().json;
const idByEmail = new Map();
let created = 0;
for (const item of $input.all()) {
  for (const r of Array.isArray(item.json.results) ? item.json.results : []) {
    const email = String(r.properties?.email || r.id || '').toLowerCase();
    if (r.id && email) idByEmail.set(email, String(r.id));
    if (r.new === true) created += 1;
  }
}
const withAssoc = (drafts, typeId) => drafts
  .filter((d) => idByEmail.has(d.email))
  .map((d) => ({ properties: d.properties, associations: [{ to: { id: idByEmail.get(d.email) }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: typeId }] }] }));

const tasks = withAssoc(composed.taskDrafts, 204);
const notes = withAssoc(composed.noteDrafts, 202);
return [{
  json: {
    contactsResolved: idByEmail.size,
    contactsCreated: created,
    unresolvedEmails: composed.taskDrafts.filter((d) => !idByEmail.has(d.email)).map((d) => d.email),
    taskBody: { inputs: tasks },
    noteBody: { inputs: notes },
  },
}];

// ─────────────────────────────────────────────────────────────────────────────
// Audit & Log Summarizer
// Final node on every path. Collects per-event outcomes, routing decisions,
// HubSpot write results and the Slack dispatch status into one audit record,
// and writes it to the n8n log for shipping to your log platform.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const parsed = $('Parse, Verify & Normalize Events').first().json;
const safeFirst = (name) => { try { return $(name).first().json; } catch (e) { return null; } };
const safeAll = (name) => { try { return $(name).all().map((i) => i.json); } catch (e) { return []; } };
const count = (rs) => rs.reduce((n, r) => n + (Array.isArray(r.results) ? r.results.length : 0), 0);
const errors = (rs) => rs.reduce((n, r) => n + (Array.isArray(r.errors) ? r.errors.length : 0), 0);

const composed = safeFirst('Compose Fallback Payloads');
const assoc = safeFirst('Attach Contact IDs to Tasks & Notes');
const upserts = safeAll('HubSpot: Upsert Contacts');
const tasks = safeAll('HubSpot: Batch Create Fallback Tasks');
const notes = safeAll('HubSpot: Batch Create Failure Notes');
const slack = safeAll('Slack: Post Fallback Alert');

let outcome;
if (!composed) outcome = parsed.events.length ? 'not_routed' : 'no_fallback_events';
else if (composed.dryRun) outcome = 'dry_run';
else if (tasks.length) outcome = 'fallback_tasks_created';
else if (composed.createFallbackTasks && composed.counts.actionable === 0) outcome = 'all_suppressed';
else outcome = 'tasks_disabled';

const audit = {
  outcome,
  runId: cfg.runId,
  executionMode: cfg.executionMode,
  sandbox: cfg.sandboxMode,
  source: parsed.source,
  signature: parsed.signature,
  intake: parsed.counters,
  rejected: parsed.rejected,
  routing: composed ? composed.routing : null,
  counts: composed ? composed.counts : null,
  outcomes: composed ? composed.outcomes : [],
  hubspot: {
    contactsUpserted: count(upserts),
    contactsCreated: assoc ? assoc.contactsCreated : 0,
    unresolvedEmails: assoc ? assoc.unresolvedEmails : [],
    tasksCreated: count(tasks),
    notesCreated: count(notes),
    errors: errors(upserts) + errors(tasks) + errors(notes),
  },
  slack: { sent: slack.length > 0, response: slack.length ? String(slack[0].data ?? slack[0].body ?? 'ok').slice(0, 40) : null },
  finishedAt: new Date().toISOString(),
};
console.log(`[routing-fallback-audit] ${JSON.stringify({ ...audit, outcomes: audit.outcomes.map((o) => ({ eventId: o.eventId, outcome: o.outcome, rule: o.rule, sdr: o.sdrEmail })) })}`);
return [{ json: audit }];
